-- ============================================================
-- Canonical 200-drill CoachVision catalog
-- ============================================================

-- Generated from drills_complete.json by scripts/generate-supabase-drill-seed.mjs.
-- Safe to re-run: canonical global drills are updated in place and missing drills are inserted.
-- Coach-owned drills and drill IDs referenced by saved plans are never deleted.

WITH catalog (coach_id, name, focus, duration, rating, verified, description, cues, tags, media_url, min_players, max_players, optimal_group_size, level, intensity, positions_emphasis, requires_full_court, is_template) AS (
