INSERT INTO public.drills (
  coach_id,
  name,
  focus,
  duration,
  rating,
  verified,
  description,
  cues,
  tags,
  media_url,
  min_players,
  max_players,
  optimal_group_size,
  level,
  intensity,
  positions_emphasis,
  requires_full_court,
  is_template
)
SELECT
  catalog.coach_id,
  catalog.name,
  catalog.focus,
  catalog.duration,
  catalog.rating,
  catalog.verified,
  catalog.description,
  catalog.cues,
  catalog.tags,
  catalog.media_url,
  catalog.min_players,
  catalog.max_players,
  catalog.optimal_group_size,
  catalog.level,
  catalog.intensity,
  catalog.positions_emphasis,
  catalog.requires_full_court,
  catalog.is_template
FROM catalog
WHERE NOT EXISTS (
  SELECT 1
  FROM public.drills AS existing
  WHERE existing.coach_id IS NULL
    AND existing.name = catalog.name
);

DO $$
BEGIN
  IF (
    SELECT COUNT(DISTINCT name)
    FROM public.drills
    WHERE coach_id IS NULL
      AND name = ANY (ARRAY['Form Shooting', 'Mikan Series', 'Reverse Mikan', 'Free Throw Routine', 'Spot-Up Shooting — 5 Spots', 'Pull-Up Series — 1-Dribble', 'Step-Back Series', 'Two-Ball Pound', 'Two-Ball Alternating', 'Cone Weave Handle', 'In-Out to Cross Combo', 'Behind-the-Back Series', 'Hesitation Series', 'Weak-Hand Only', 'Euro-Step Finishes', 'Floater Series', 'Spin Move Finish', '3-Man Weave', '4-Corners Passing', 'Partner Chest Pass', 'Partner Bounce Pass', 'Skip Pass Reads', 'Paint Touch Kicks', 'Shell Defense 4v4', 'Help & Recover', 'Closeout & Contest', 'Zig-Zag Defense', 'Box-Out Gauntlet', 'Outlet & Fill', 'Baseline Sprints', 'Suicides (Line Runs)', 'Lane Agility Test', 'Baseline-to-Baseline Repeats', 'Ball Screen Pull-Up', 'Pistol Action (DHO)', 'Hammer Action', 'Star Shooting (5-Spot)', 'Chair Shooting — Curls & Fades', 'Drive-Kick-Swing 3s', 'PnR Reads — Drop Coverage', 'PnR Reads — Switch & Slip', 'Post Entry & 45 Cut', 'Relocation Shooting', 'Nail Help Scramble (2v2+Coach)', 'Baseline Drift Coverage', 'Corner Closeouts', 'Shell + Ball Screen Layer', '3-Man Weave into 3v2', '4-Man Weave into 2v1', 'Skip to Extra', 'Numbers Advantage — 5v4', 'Full-Court Conditioning — 17s', '30-30-30 Runs', 'Shuttle Sprints (Pro)', 'Zoom Action Reads', 'Ghost Screen 3s', 'Drift-Corner Series', 'Punch Post Seal', 'Laker Cut Finishes', 'Iverson Cut Catch & Shoot', 'Floppy Action Var 1', 'Floppy Action Var 2', 'Staggered Screens Reads', 'Spain PnR Finisher', 'Chicago Action (Pin+DHO)', 'Zoom Flip Late Clock', 'Short Roll Playmaking', 'Skip to Hammer', 'Nash Dribble Under', 'Lift & Drift Shooting', 'Stack Inbounds Quick 3', 'Baseline Rip Screen', 'Wedge Screen Post-Up', 'Spain Twist Variation', 'Double Drag Options', 'Drag into Throwback 3', 'Empty-Side PnR Reads', 'Veer Back Read', 'Pitch Ahead Layups', 'Deep Seal Duck-Ins', 'Punch to Split Cut', 'Wide Pindown to DHO', 'Pindown Slip & Pop', 'Post Split to Corner 3', 'K-Slide Closeout Chain', 'Gap & Go Contest', 'Tag