rill', 'Contain Drill', 'Punch Flow', 'Lift Flow', 'Blitz Rotation', 'Peel Coverage', 'Ladder Tempo', 'Swing Timing', 'Switch Discipline', 'Gap Drill', 'Repeat Test', 'Tag Chain', 'Chicago Action Var']::TEXT[])
  ) <> 200 THEN
